import { useState } from 'react';
import { Button, Card, Input, Stack, Text } from '@jinx-ui/react';

export type SignUpValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type SignUpWizardProps = {
  onSubmit: (values: SignUpValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_VALUES: SignUpValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function SignUpWizard({ onSubmit }: SignUpWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignUpValues>(EMPTY_VALUES);

  const isLastStep = step === STEPS.length - 1;

  const update =
    (field: keyof SignUpValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const next = event.target.value;
      setValues((current) => ({ ...current, [field]: next }));
    };

  const goBack = () => setStep((current) => Math.max(0, current - 1));

  const goNext = () => {
    if (isLastStep) {
      onSubmit(values);
      return;
    }
    setStep((current) => current + 1);
  };

  return (
    <Card>
      <Stack direction="column" gap="lg">
        <Stack
          direction="row"
          gap="md"
          role="list"
          aria-label="Шаги регистрации"
        >
          {STEPS.map((label, index) => {
            const isDone = index < step;
            const isCurrent = index === step;
            const accent = isDone || isCurrent
              ? 'var(--jx-color-primary)'
              : 'var(--jx-color-border)';

            return (
              <Stack
                key={label}
                direction="row"
                gap="sm"
                role="listitem"
                aria-current={isCurrent ? 'step' : undefined}
              >
                <span
                  aria-hidden="true"
                  style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    inlineSize: 'var(--jx-space-lg)',
                    blockSize: 'var(--jx-space-lg)',
                    borderRadius: 'var(--jx-radius-full)',
                    border: `var(--jx-border-width-sm) solid ${accent}`,
                    background: isCurrent ? accent : 'transparent',
                    color: isCurrent
                      ? 'var(--jx-color-primary-contrast)'
                      : 'var(--jx-color-text-muted)',
                  }}
                >
                  {index + 1}
                </span>
                <Text
                  weight={isCurrent ? 'bold' : 'regular'}
                  style={{
                    color: isCurrent
                      ? 'var(--jx-color-text)'
                      : 'var(--jx-color-text-muted)',
                  }}
                >
                  {label}
                </Text>
              </Stack>
            );
          })}
        </Stack>

        {step === 0 && (
          <Stack direction="column" gap="md">
            <Input label="Имя" value={values.name} onChange={update('name')} />
            <Input
              label="Email"
              type="email"
              value={values.email}
              onChange={update('email')}
            />
            <Input
              label="Телефон"
              type="tel"
              value={values.phone}
              onChange={update('phone')}
            />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="column" gap="md">
            <Input
              label="Страна"
              value={values.country}
              onChange={update('country')}
            />
            <Input label="Город" value={values.city} onChange={update('city')} />
            <Input
              label="Улица и дом"
              value={values.street}
              onChange={update('street')}
            />
            <Input
              label="Индекс"
              value={values.zip}
              onChange={update('zip')}
            />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="column" gap="sm">
            <Text weight="bold">Проверьте данные</Text>
            <Text>Имя: {values.name}</Text>
            <Text>Email: {values.email}</Text>
            <Text>Телефон: {values.phone}</Text>
            <Text>
              Адрес: {values.country}, {values.city}, {values.street}, {values.zip}
            </Text>
          </Stack>
        )}

        <Stack direction="row" gap="md" justify="end">
          <Button variant="secondary" onClick={goBack} disabled={step === 0}>
            Назад
          </Button>
          <Button variant="primary" onClick={goNext}>
            {isLastStep ? 'Отправить' : 'Дальше'}
          </Button>
        </Stack>
      </Stack>
    </Card>
  );
}

